<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('Administrator','IT');$pageTitle='Audit Trail';$rows=db()->query("SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 150")->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Security & accountability</div><h1 class="admin-title">Audit trail</h1></div></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y H:i:s',strtotime($r['created_at']))?></td><td><?=e($r['full_name']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['entity_type'])?> #<?=e((string)$r['entity_id'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php'; ?>
